    ('4fddfa2d169e6aa1800d28ca45de0bb9ef1c22a11a6eef5d4b1258c72bf34511', 'about', 'adverb', 'I looked about at the scenery that surrounded me.', 'She looked about before crossing the street.', 'Cô ấy nhìn xung quanh trước khi qua đường.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
