    ('119d04ba188b43ac419b22fbc5c0561af27e813e62ecc5e8de92382f4fbb131e', 'agree', 'verb', 'all parties agree in the expediency of the law.', 'I agree with you about the plan.', 'Tôi đồng ý với bạn về kế hoạch đó.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('003ed83b3aa93126538a15559e1b52059a45b599f92185d08aae7dbf1d695ec1', 'airport', 'noun', NULL, 'We met at the airport.', 'Chúng tôi gặp nhau ở sân bay.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('3021cdc1049167a702de381671d5318a46c38407046d878cdfcdb7e5bc8121b2', 'album', 'noun', NULL, 'I put the photos in an album.', 'Tôi cho những tấm ảnh vào một tập ảnh.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('3d269d0955fbfc9dc32ab2cf43d25228b341ded47ea5388aff07335ae3ef9cd7', 'all right', 'adjective', 'The car is all right. It gets me there, anyway.', 'The hotel room is all right.', 'Phòng khách sạn cũng tạm ổn.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('5c096265271785a72cf3c61ed3283924a775109a9cb8a6fbc22970e857127eff', 'almost', 'adverb', 'Almost all people went there. - Not all but very close to it.', 'Almost everyone came to the party.', 'Gần như ai cũng đến dự tiệc.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
