    ('623c74a0a7d3435a785e31be696428d8e18be6c08e45d5f88f5a7205e1fe68d1', 'also', 'adverb', 'They had porridge for breakfast, and also toast.', 'They had porridge for breakfast, and also toast.', 'Họ ăn cháo vào bữa sáng, và cũng ăn bánh mì nướng.', '{"english": "Free Dictionary API", "englishUrl": "https://api.dictionaryapi.dev/api/v2/entries/en/also", "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('664295b57679229512d6268c272dde0b52ffc5e9a047369c8588deb1b749ca65', 'always', 'adverb', 'Airplanes did not always exist as a form of transportation.', 'I always bring water to school.', 'Tôi luôn mang nước đến trường.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('281841cc59a4cec38c54023cd4f76e8b082f17d074aeb32cd7cfbe15dceec72d', 'and', 'conjunction', NULL, 'I bought bread and milk.', 'Tôi mua bánh mì và sữa.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('170fed4ffbb4db45daf34f765070d13ebdfd969ed2adbea50b272ca7bf1288de', 'angry', 'adjective', 'An angry mob started looting the warehouse.', 'He was angry when I broke his cup.', 'Anh ấy tức giận khi tôi làm vỡ cốc của anh ấy.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('86e245fbd35e45141d5775366b75ff1dc8407a8952925bb2373bd8bfc34e0bb5', 'animal', 'noun', 'A cat is an animal, not a plant. Humans are also animals, under the scientific definition, as we are not plants.', 'A rabbit is a small animal.', 'Thỏ là một loài động vật nhỏ.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('0460e3a556fe245574ad3226d8baaf3c62a1f886d56bad89e37f772d0fb6c4e0', 'answer', 'noun', 'Her answer to his proposal was a slap in the face.', 'I know the answer to this question.', 'Tôi biết câu trả lời cho câu hỏi này.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('c079e340e4885f227eaac96600db0b2bc44e8751b65d2da6096c7b17942527ca', 'answer', 'verb', 'He answered the question.', 'He answered the question.', 'Anh ấy đã trả lời câu hỏi.', '{"english": "Free Dictionary API", "englishUrl": "https://api.dictionaryapi.dev/api/v2/entries/en/answer", "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('5827748eff42d1f53b8d43598e056939900059af8f5e0f87134338654497245e', 'any', 'pronoun', 'Any may apply.', 'Any may apply.', 'Ai cũng có thể nộp đơn.', '{"english": "Free Dictionary API", "englishUrl": "https://api.dictionaryapi.dev/api/v2/entries/en/any", "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('8ec6250aba7c204bea0994ff741006f34a0e92d59e3158b9821f69933a3851a1', 'anybody', 'pronoun', 'Anybody will do.', 'I''ll play with anybody.', 'Tôi sẽ chơi với bất cứ ai.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('73005242d746894adcc8bde2a6354b8d9f06cbe128384924245fb7f919475cdf', 'anyone', 'pronoun', 'Almost anyone can change a light bulb.', 'Almost anyone can change a light bulb.', 'Gần như ai cũng có thể thay bóng đèn.', '{"english": "Free Dictionary API", "englishUrl": "https://api.dictionaryapi.dev/api/v2/entries/en/anyone", "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('3d010589c26da7db5a369b7312264961923b5ecbcc81bf5bf632565f913104c1', 'anything', 'pronoun', 'I would not do it for anything.', 'I didn''t buy anything.', 'Tôi không mua gì cả.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('e666ec16175a04c5e5a972c690be399aa17175bf0fc2b9cad2fe2aa172d753b7', 'apple', 'noun', NULL, 'She ate an apple after lunch.', 'Cô ấy ăn một quả táo sau bữa trưa.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('77d97bf423869762160b062eac96f415968f40196deb802299afaa14f90bb0e4', 'apron', 'noun', NULL, 'I wear an apron when I cook.', 'Tôi đeo tạp dề khi nấu ăn.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('165693b019e94d0e70e10df2f48420ecb73b3a20918f7589a529a05033ed676e', 'arm', 'noun', 'She stood with her right arm extended and her palm forward to indicate “Stop!”', 'She raised her right arm.', 'Cô ấy giơ cánh tay phải lên.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('d99988b29d6961d69729dd9bb1f728efbdc476795d626560eaa98fa01875f1c2', 'around', 'preposition', 'I planted a row of lilies around the statue.', 'We sat around the table.', 'Chúng tôi ngồi vòng quanh bàn.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('f430135d94dc9eb3b4e90895b8046600e829d32ab9b1d7f07ee5bef1c072a081', 'arrive', 'verb', 'He arrived home for two days.', 'They arrived at the station at noon.', 'Họ đến nhà ga vào buổi trưa.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('e0cb1796a698c957afa0bd942bd9793704b46d89f9a081d5ecadcfbd35c2b768', 'art', 'noun', 'There is a debate as to whether graffiti is art or vandalism.', 'The children made art with paint and paper.', 'Các em sáng tạo tác phẩm nghệ thuật bằng màu vẽ và giấy.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('e17b5875e9ef7b27ba7e57e32a6f5470e40d43f24482d593043361fee28e1c3c', 'ask', 'verb', 'I asked her age.', 'I asked her age.', 'Tôi hỏi cô ấy bao nhiêu tuổi.', '{"english": "Free Dictionary API", "englishUrl": "https://api.dictionaryapi.dev/api/v2/entries/en/ask", "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('1cca14a1ca5871a951d06b2ab452dd1adb8077d9ba992056fc91b66a480cf361', 'at', 'preposition', 'Caesar was at Rome;  at the corner of Fourth Street and Vine;  at Jim’s house', 'Meet me at the library.', 'Gặp tôi ở thư viện nhé.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('53c7e661c4121199ac113e2772be8b8d00dffdde5a84f74ae14a7464b741164e', 'aunt', 'noun', NULL, 'My aunt is my mother''s younger sister.', 'Dì tôi là em gái của mẹ tôi.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('c4dfaca0297671bac68f6dca1f2f3e6bc38316e135443802c8f0145f203a19d0', 'autumn', 'noun', NULL, 'The leaves turn yellow in autumn.', 'Lá chuyển sang màu vàng vào mùa thu.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('d013d8b0cbad37b411db709c3e4d638aa7691d2c6b3f08926ce9fb2c39b96846', 'away', 'adverb', 'He went away on vacation.', 'He went away on vacation.', 'Anh ấy đi xa để nghỉ mát.', '{"english": "Free Dictionary API", "englishUrl": "https://api.dictionaryapi.dev/api/v2/entries/en/away", "vietnamese": "English Learning App (example translation)"}'::jsonb),
    ('281fe5670aa97ddead163602e0704e7ca97400564767ad29feb27755b8c5f6d5', 'baby', 'noun', 'When is your baby due?', 'The baby is sleeping.', 'Em bé đang ngủ.', '{"english": "English Learning App (original example)", "englishUrl": null, "vietnamese": "English Learning App (example translation)"}'::jsonb)
  ) AS expected(import_key, headword, part_of_speech, previous_en, en, vi, metadata)
  LOOP
    UPDATE public.words w
    SET example_en = pair.en,
        example_vi = pair.vi,
        source_metadata = w.source_metadata || jsonb_build_object('examples', pair.metadata)
    WHERE w.import_key = pair.import_key
      AND w.headword = pair.headword AND w.part_of_speech = pair.part_of_speech
      AND w.example_en IS NOT DISTINCT FROM pair.previous_en
      AND w.example_vi IS NULL
      AND NOT (w.source_metadata ? 'examples');

    IF FOUND THEN
      updated_count := updated_count + 1;
    ELSIF NOT EXISTS (SELECT 1 FROM public.words w
      WHERE w.import_key = pair.import_key
        AND w.headword = pair.headword AND w.part_of_speech = pair.part_of_speech
        AND w.example_en = pair.en AND w.example_vi = pair.vi
        AND w.source_metadata -> 'examples' = pair.metadata) THEN
      RAISE EXCEPTION 'Word example is missing or was edited: % (%)', pair.headword, pair.part_of_speech;
    END IF;
  END LOOP;
  RAISE NOTICE 'Week 4 example pairs updated: % of 43', updated_count;
END $week4_examples$;

COMMIT;
